        lesson_metadata: {
          lesson_id: "N4-L31",
          lesson_number: 31,
          module_number: 7,
          module_name: "Nuance, Modals & N4 Capstone",
          module_name_bn: "\u09AC\u09BE\u09B9\u09CD\u09AF\u09BF\u0995 \u09B0\u09C2\u09AA, \u09AE\u09BE\u09A4\u09CD\u09B0\u09BE \u0993 \u09AA\u09C2\u09B0\u09CD\u09A3\u09BE\u0999\u09CD\u0997 N4 \u09AA\u09CD\u09B0\u09B8\u09CD\u09A4\u09C1\u09A4\u09BF",
          title_ja: "\u69D8\u614B[\u3088\u3046\u305F\u3044]\u3068\u4F1D\u805E[\u3067\u3093\u3076\u3093]",
          title_en: "Conjecture by Appearance vs Hearsay (~sou desu)",
          title_bn: "\u09AC\u09BE\u09B9\u09CD\u09AF\u09BF\u0995 \u09A6\u09C3\u09B7\u09CD\u099F\u09BF\u09A4\u09C7 \u0985\u09A8\u09C1\u09AD\u09C2\u09A4\u09BF \u09AC\u09A8\u09BE\u09AE \u09B2\u09CB\u0995\u09AE\u09C1\u0996\u09C7 \u09B6\u09CB\u09A8\u09BE \u09A4\u09A5\u09CD\u09AF (~\u09B8\u09CC\u0995 \u09A6\u09C7\u09B8\u09C1)",
          estimated_minutes: 35,
          difficulty: "Intermediate"
        },
        bengali_bridge: {
          explanation_bn: "\u099C\u09BE\u09AA\u09BE\u09A8\u09BF \u09AD\u09BE\u09B7\u09BE\u09AF\u09BC \u301C\u305D\u3046\u3067\u3059 (sou desu) \u09A6\u09C1\u099F\u09BF \u09B8\u09AE\u09CD\u09AA\u09C2\u09B0\u09CD\u09A3 \u09AD\u09BF\u09A8\u09CD\u09A8 \u09AC\u09CD\u09AF\u09BE\u0995\u09B0\u09A3\u0997\u09A4 \u0985\u09B0\u09CD\u09A5\u09C7 \u09AC\u09CD\u09AF\u09AC\u09B9\u09C3\u09A4 \u09B9\u09AF\u09BC: \u09E7. \u09AC\u09BE\u09B9\u09CD\u09AF\u09BF\u0995 \u09B0\u09C2\u09AA \u09AC\u09BE \u0985\u09A8\u09C1\u09AD\u09C2\u09A4\u09BF (\u69D8\u614B - Appearance): \u0995\u09CB\u09A8\u09CB \u09AC\u09B8\u09CD\u09A4\u09C1 \u09A6\u09C7\u0996\u09C7 \u09AE\u09A8\u09C7 \u09B9\u0993\u09AF\u09BC\u09BE \u09A4\u09BE \u09B8\u09C1\u09B8\u09CD\u09AC\u09BE\u09A6\u09C1, \u09AD\u09BE\u09B0\u09C0 \u09AC\u09BE \u09AC\u09C3\u09B7\u09CD\u099F\u09BF \u09B9\u09A4\u09C7 \u099A\u09B2\u09C7\u099B\u09C7 (\u0995\u09CD\u09B0\u09BF\u09AF\u09BC\u09BE \u307E\u3059\u5F62\u8A9E\u5E79 / \u09AC\u09BF\u09B6\u09C7\u09B7\u09A3 \u0997\u09CB\u09A1\u09BC\u09BE + \u305D\u3046\u3067\u3059; \u09AF\u09C7\u09AE\u09A8: \u96E8\u304C\u964D\u308A\u305D\u3046\u3067\u3059 - \u09AC\u09C3\u09B7\u09CD\u099F\u09BF \u09A8\u09BE\u09AE\u09BE\u09B0 \u0989\u09AA\u0995\u09CD\u09B0\u09AE / \u7F8E\u5473\u3057\u305D\u3046\u3067\u3059 - \u09A6\u09C7\u0996\u09A4\u09C7 \u09B8\u09C1\u09B8\u09CD\u09AC\u09BE\u09A6\u09C1 \u09B2\u09BE\u0997\u099B\u09C7); \u09E8. \u09B6\u09CB\u09A8\u09BE \u0995\u09A5\u09BE \u09AC\u09BE \u099C\u09A8\u09B6\u09CD\u09B0\u09C1\u09A4\u09BF (\u4F1D\u805E - Hearsay): \u09AA\u09A4\u09CD\u09B0\u09BF\u0995\u09BE, \u0996\u09AC\u09B0 \u09AC\u09BE \u0985\u09A8\u09CD\u09AF \u0995\u09BE\u09B0\u09CB \u0995\u09BE\u099B \u09A5\u09C7\u0995\u09C7 \u09B6\u09CB\u09A8\u09BE \u09A4\u09A5\u09CD\u09AF \u09B9\u09C1\u09AC\u09B9\u09C1 \u0989\u09A6\u09CD\u09A7\u09C3\u09A4 \u0995\u09B0\u09BE (\u09B8\u09BE\u09A7\u09BE\u09B0\u09A3 \u09B0\u09C2\u09AA Plain form + \u305D\u3046\u3067\u3059; \u09AF\u09C7\u09AE\u09A8: \u660E\u65E5\u306F\u96E8\u304C\u964D\u308B\u305D\u3046\u3067\u3059 - \u09B6\u09C1\u09A8\u09C7\u099B\u09BF \u0995\u09BE\u09B2 \u09AC\u09C3\u09B7\u09CD\u099F\u09BF \u09B9\u09AC\u09C7)\u0964",
          core_concept_bn: "\u09A6\u09C7\u0996\u09C7 \u09AE\u09A8\u09C7 \u09B9\u0993\u09AF\u09BC\u09BE: \u307E\u3059/\u3044 \u09AC\u09BE\u09A6 + \u305D\u3046\u3067\u3059 (\u7F8E\u5473\u3057\u305D\u3046); \u09B6\u09C1\u09A8\u09C7 \u09AC\u09B2\u09BE: \u666E\u901A\u5F62 + \u305D\u3046\u3067\u3059 (\u7F8E\u5473\u3057\u3044\u305D\u3046\u3067\u3059)\u0964",
          real_world_context_bn: "\u09B0\u09C7\u09B8\u09CD\u09A4\u09CB\u09B0\u09BE\u0981\u09B0 \u09A1\u09BF\u09B8\u09AA\u09CD\u09B2\u09C7 \u09A6\u09C7\u0996\u09C7 \u0996\u09BE\u09AC\u09BE\u09B0 \u0985\u09B0\u09CD\u09A1\u09BE\u09B0 \u0995\u09B0\u09BE (\u7F8E\u5473\u3057\u305D\u3046!) \u098F\u09AC\u0982 \u099C\u09BE\u09AA\u09BE\u09A8\u09BF \u09AC\u09A8\u09CD\u09A7\u09C1\u09A6\u09C7\u09B0 \u0995\u09BE\u099B \u09A5\u09C7\u0995\u09C7 \u0986\u09AC\u09B9\u09BE\u0993\u09AF\u09BC\u09BE \u09AC\u09BE \u099F\u09CD\u09B0\u09C7\u09A8\u09C7\u09B0 \u0996\u09AC\u09B0 \u09B6\u09CB\u09A8\u09BE\u0964",
          key_takeaway_bn: "\u3044\u3044 (\u09AD\u09BE\u09B2\u09CB) \u098F\u09B0 \u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u09C7 \u09A6\u09C3\u09B6\u09CD\u09AF\u09AE\u09BE\u09A8 \u0985\u09A8\u09C1\u09AD\u09C2\u09A4\u09BF \u09B9\u09B2\u09CB \u3088\u3055\u305D\u3046 (Yosasou)\u0964"
        },
