        bengali_bridge: {
          explanation_bn: "\u0985\u09AD\u09BF\u09A8\u09A8\u09CD\u09A6\u09A8! \u0986\u09AA\u09A8\u09BF \u09B8\u09AB\u09B2\u09AD\u09BE\u09AC\u09C7 N4 \u0995\u09BE\u09B0\u09BF\u0995\u09C1\u09B2\u09BE\u09AE\u09C7\u09B0 \u09E9\u09EB\u099F\u09BF \u09AE\u09CC\u09B2\u09BF\u0995 \u0985\u09A7\u09CD\u09AF\u09BE\u09AF\u09BC \u09B8\u09AE\u09BE\u09AA\u09CD\u09A4 \u0995\u09B0\u09C7\u099B\u09C7\u09A8\u0964 \u098F\u0987 \u09B8\u09AE\u09BE\u09AA\u09A8\u09C0 \u0985\u09A7\u09CD\u09AF\u09BE\u09AF\u09BC\u09C7 N4 \u09B8\u09CD\u09A4\u09B0\u09C7\u09B0 \u09AC\u09CD\u09AF\u09BE\u0995\u09B0\u09A3\u09C7\u09B0 \u09B8\u09BE\u09AE\u0997\u09CD\u09B0\u09BF\u0995 \u09B8\u09AE\u09A8\u09CD\u09AC\u09AF\u09BC, \u0995\u09C7\u0987\u0997\u09CB (\u09B8\u09CB\u09A8\u0995\u09C7\u0987\u0997\u09CB \u0993 \u0995\u09C7\u09A8\u099C\u09CC\u0997\u09CB), \u09AA\u09CD\u09AF\u09BE\u09B8\u09BF\u09AD \u0993 \u0995\u099C\u09C7\u099F\u09BF\u09AD \u09AA\u09CD\u09AF\u09BE\u09B8\u09BF\u09AD\u09C7\u09B0 \u09B8\u0982\u09AE\u09BF\u09B6\u09CD\u09B0\u09A3, \u098F\u09AC\u0982 \u09AC\u09BE\u09B8\u09CD\u09A4\u09AC \u09B0\u09BF\u09A1\u09BF\u0982 \u0995\u09AE\u09AA\u09CD\u09B0\u09BF\u09B9\u09C7\u09A8\u09B6\u09A8 (\u8AAD\u89E3) \u0993 \u09B2\u09BF\u09B8\u09C7\u09A8\u09BF\u0982 (\u8074\u89E3) \u098F\u09B0 \u0995\u09CC\u09B6\u09B2 \u09AA\u09C2\u09B0\u09CD\u09A3\u09BE\u0999\u09CD\u0997\u09AD\u09BE\u09AC\u09C7 \u0985\u09A8\u09C1\u09B6\u09C0\u09B2\u09A8 \u0995\u09B0\u09BE\u09A8\u09CB \u09B9\u09AC\u09C7\u0964 N4 \u09AA\u09BE\u09B8 \u0995\u09B0\u09BE \u09AE\u09BE\u09A8\u09C7 \u0986\u09AA\u09A8\u09BF \u099C\u09BE\u09AA\u09BE\u09A8\u09C7 \u09B8\u09CD\u09AC\u09BE\u09A7\u09C0\u09A8\u09AD\u09BE\u09AC\u09C7 \u09A6\u09C8\u09A8\u09A8\u09CD\u09A6\u09BF\u09A8 \u099C\u09C0\u09AC\u09A8 \u0993 \u09AA\u09CD\u09B0\u09AB\u09C7\u09B6\u09A8\u09BE\u09B2 \u0995\u09AE\u09BF\u0989\u09A8\u09BF\u0995\u09C7\u09B6\u09A8\u09C7\u09B0 \u09AA\u09CD\u09B0\u09BE\u09A5\u09AE\u09BF\u0995 \u09AD\u09BF\u09A4 \u09AE\u099C\u09AC\u09C1\u09A4 \u0995\u09B0\u09C7\u099B\u09C7\u09A8\u0964",
          core_concept_bn: "N4 \u09AC\u09CD\u09AF\u09BE\u0995\u09B0\u09A3 \u09B8\u09AE\u09A8\u09CD\u09AC\u09AF\u09BC: \u656C\u8A9E (\u5C0A\u656C/\u8B19\u8B72), \u53D7\u8EAB/\u4F7F\u5F79, 4\u3064\u306E\u6761\u4EF6 (\u3068\u30FB\u3070\u30FB\u305F\u3089\u30FB\u306A\u3089), \u8907\u5408\u8868\u73FE (\u301C\u3066\u304A\u304F\u3001\u301C\u3066\u3042\u308B\u3001\u301C\u3066\u3057\u307E\u3046)\u0964",
          real_world_context_bn: "JLPT N4 \u0985\u09AB\u09BF\u09B8\u09BF\u09AF\u09BC\u09BE\u09B2 \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE\u09B0 \u09B9\u09B2, \u09B8\u09CD\u09AA\u09C7\u09B8\u09BF\u09AB\u09BE\u0987\u09A1 \u09B8\u09CD\u0995\u09BF\u09B2\u09A1 \u0993\u09AF\u09BC\u09BE\u09B0\u09CD\u0995\u09BE\u09B0 (SSW/\u099F\u09CB\u0995\u09C1\u09A4\u09C7\u0987 \u0997\u09BF\u09A8\u09CB) \u09AD\u09BF\u09B8\u09BE \u0993 \u099C\u09BE\u0987\u09B0\u09BF\u0989 \u0995\u09BE\u09B0\u09CD\u09A1 \u09A8\u09AC\u09BE\u09AF\u09BC\u09A8\u09C7\u0964",
          key_takeaway_bn: "\u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE\u09AF\u09BC \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BF \u09AA\u09CD\u09B0\u09B6\u09CD\u09A8\u09C7\u09B0 \u0995\u09A8\u099F\u09C7\u0995\u09CD\u09B8\u099F (\u0995\u09C7 \u0995\u09BE\u0995\u09C7 \u09AC\u09B2\u099B\u09C7 \u098F\u09AC\u0982 \u0995\u09C0 \u09AA\u09B0\u09BF\u09B8\u09CD\u09A5\u09BF\u09A4\u09BF\u09A4\u09C7 \u09AC\u09B2\u099B\u09C7) \u09AC\u09CB\u099D\u09BE \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u0997\u09C1\u09B0\u09C1\u09A4\u09CD\u09AC\u09AA\u09C2\u09B0\u09CD\u09A3\u0964"
        },
