        lesson_metadata: {
          lesson_id: "N3-L05",
          lesson_number: 5,
          module_number: 1,
          module_name: "\u6642 (Timing & Sequence)",
          module_name_bn: "\u09B8\u09AE\u09DF \u0993 \u09A7\u09BE\u09B0\u09BE\u09AC\u09BE\u09B9\u09BF\u0995\u09A4\u09BE",
          title_ja: "\u301C\u305F\u3073\u306B\u306E\u7528\u6CD5[\u3088\u3046\u307B\u3046]",
          title_en: "Every Time / Whenever (~tabini)",
          title_bn: "\u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u09AC\u09BE \u09AF\u0996\u09A8\u0987 \u098F\u09AE\u09A8 \u09B9\u09AF\u09BC (~\u305F\u3073\u306B)",
          estimated_minutes: 30,
          difficulty: "Intermediate"
        },
        bengali_bridge: {
          explanation_bn: "\u301C\u305F\u3073\u306B (tabini) \u09AA\u09CD\u09B0\u0995\u09BE\u09B6 \u0995\u09B0\u09C7: \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0 \u09AF\u0996\u09A8\u0987 \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F \u0995\u09BE\u099C\u099F\u09BF \u0995\u09B0\u09BE \u09B9\u09AF\u09BC, \u09A0\u09BF\u0995 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u0985\u09AC\u09A7\u09BE\u09B0\u09BF\u09A4\u09AD\u09BE\u09AC\u09C7 \u098F\u0995\u0987 \u09AE\u09BE\u09A8\u09B8\u09BF\u0995 \u0985\u09A8\u09C1\u09AD\u09C2\u09A4\u09BF \u09AC\u09BE \u09AB\u09B2\u09BE\u09AB\u09B2 \u09AC\u09BE\u09B0\u09AC\u09BE\u09B0 \u09AB\u09BF\u09B0\u09C7 \u0986\u09B8\u09C7\u0964 \u098F\u099F\u09BF \u09A8\u09BF\u09AF\u09BC\u09AE\u09BF\u09A4 \u09AA\u09C1\u09A8\u09B0\u09BE\u09AC\u09C3\u09A4\u09CD\u09A4\u09BF\u09B0 \u09B8\u09C2\u09A4\u09CD\u09B0 \u09A4\u09C8\u09B0\u09BF \u0995\u09B0\u09C7\u0964",
          core_concept_bn: "\u0995\u09CB\u09A8\u09CB \u0995\u09BE\u099C \u0995\u09B0\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u098F\u0995\u0987 \u09AB\u09B2 \u09AC\u09BE \u0986\u09AC\u09C7\u0997\u09C7\u09B0 \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u09AA\u09C1\u09A8\u09B0\u09BE\u09AC\u09C3\u09A4\u09CD\u09A4\u09BF \u0998\u099F\u09BE\u0964",
          real_world_context_bn: "\u09AF\u0996\u09A8\u0987 \u09A6\u09C7\u09B6\u09C7\u09B0 \u09AA\u09C1\u09B0\u09BE\u09A8\u09CB \u099B\u09AC\u09BF \u09A6\u09C7\u0996\u09BF, \u09AE\u09A8\u099F\u09BE \u09B8\u09CD\u09AE\u09C3\u09A4\u09BF\u09AD\u09BE\u09B0\u09BE\u0995\u09CD\u09B0\u09BE\u09A8\u09CD\u09A4 \u09B9\u09AF\u09BC\u09C7 \u0993\u09A0\u09C7 (\u5199\u771F\u3092\u898B\u308B\u305F\u3073\u306B\u6545\u90F7\u3092\u601D\u3044\u51FA\u3059) \u09AC\u09BE \u09AF\u0996\u09A8\u0987 \u0993\u0987 \u09A6\u09CB\u0995\u09BE\u09A8\u09C7 \u09AF\u09BE\u0987, \u09A8\u09A4\u09C1\u09A8 \u09AC\u0987 \u0995\u09BF\u09A8\u09C7 \u09AB\u09C7\u09B2\u09BF\u2014\u098F\u09AE\u09A8 \u09AA\u09B0\u09BF\u09B8\u09CD\u09A5\u09BF\u09A4\u09BF\u09A4\u09C7 \u305F\u3073\u306B \u09AC\u09B8\u09C7\u0964",
          key_takeaway_bn: "\u52D5\u8A5E\u8F9E\u66F8\u5F62 / \u540D\u8A5E+\u306E + \u305F\u3073\u306B\u0964 \u09A8\u09BF\u09A4\u09CD\u09AF\u09A6\u09BF\u09A8\u09C7\u09B0 \u09B8\u09CD\u09AC\u09BE\u09AD\u09BE\u09AC\u09BF\u0995 \u09A7\u09BE\u09B0\u09BE\u09AC\u09BE\u09B9\u09BF\u0995\u09A4\u09BE (\u09AF\u09C7\u09AE\u09A8: \u09B8\u0995\u09BE\u09B2 \u09B9\u09B2\u09C7\u0987 \u0998\u09C1\u09AE \u09AD\u09BE\u0999\u09C7) \u09AC\u09CB\u099D\u09BE\u09A4\u09C7 \u09AC\u09B8\u09C7 \u09A8\u09BE; \u09AC\u09B0\u0982 \u0985\u09A8\u09C1\u09AD\u09C2\u09A4\u09BF \u0993 \u0986\u099A\u09B0\u09A3\u09C7\u09B0 \u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u09C7 \u09AC\u09B8\u09C7\u0964"
        },
        vocabulary_scope: [
          {
            word_ja: "\u6545\u90F7[\u3053\u304D\u3087\u3046]",
            romaji: "kokyou",
            meaning_bn: "\u099C\u09A8\u09CD\u09AE\u09AD\u09C2\u09AE\u09BF / \u09A6\u09C7\u09B6\u09C7\u09B0 \u09AC\u09BE\u09A1\u09BC\u09BF",
            meaning_en: "hometown / birthplace",
            part_of_speech: "noun",
            example_ja: "\u3053\u306E\u6B4C[\u3046\u305F]\u3092\u8074[\u304D]\u304F\u305F\u3073\u306B\u6545\u90F7[\u3053\u304D\u3087\u3046]\u3092\u601D[\u304A\u3082]\u3044\u51FA[\u3060]\u3059\u3002",
            example_bn: "\u098F\u0987 \u0997\u09BE\u09A8\u099F\u09BF \u09B6\u09CB\u09A8\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u09A6\u09C7\u09B6\u09C7\u09B0 \u09AC\u09BE\u09A1\u09BC\u09BF\u09B0 \u0995\u09A5\u09BE \u09AE\u09A8\u09C7 \u09AA\u09A1\u09BC\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964",
            example_en: "Every time I listen to this song, I remember my hometown."
          },
          {
            word_ja: "\u601D[\u304A\u3082]\u3044\u51FA[\u3060]\u3059",
            romaji: "omoidasu",
            meaning_bn: "\u09B8\u09CD\u09AE\u09B0\u09A3 \u0995\u09B0\u09BE / \u09AE\u09A8\u09C7 \u09AA\u09A1\u09BC\u09BE",
            meaning_en: "to recall / remember",
            part_of_speech: "verb",
            example_ja: "\u30A2\u30EB\u30D0\u30E0\u3092\u898B[\u307F]\u308B\u305F\u3073\u306B\u6614[\u3080\u304B\u3057]\u3092\u601D[\u304A\u3082]\u3044\u51FA[\u3060]\u3059\u3002",
            example_bn: "\u0985\u09CD\u09AF\u09BE\u09B2\u09AC\u09BE\u09AE\u099F\u09BF \u09A6\u09C7\u0996\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u0985\u09A4\u09C0\u09A4 \u09B8\u09CD\u09AE\u09C3\u09A4\u09BF \u09AE\u09A8\u09C7 \u09AA\u09A1\u09BC\u09C7\u0964",
            example_en: "Whenever I look at the album, I recall the past."
          },
          {
            word_ja: "\u5F8C\u6094[\u3053\u3046\u304B\u3044]\u3059\u308B",
            romaji: "koukai suru",
            meaning_bn: "\u0985\u09A8\u09C1\u09A4\u09BE\u09AA \u0995\u09B0\u09BE / \u0986\u09AB\u09B8\u09CB\u09B8 \u0995\u09B0\u09BE",
            meaning_en: "to regret / repent",
            part_of_speech: "verb",
            example_ja: "\u7121\u99C4\u9063[\u3080\u3060\u3065\u304B]\u3044\u3092\u3059\u308B\u305F\u3073\u306B\u5F8C\u6094[\u3053\u3046\u304B\u3044]\u3059\u308B\u3002",
            example_bn: "\u0985\u09B9\u09C7\u09A4\u09C1\u0995 \u0985\u09AA\u099A\u09AF\u09BC \u0995\u09B0\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u0986\u09AE\u09BF \u0985\u09A8\u09C1\u09A4\u09AA\u09CD\u09A4 \u09B9\u0987\u0964",
            example_en: "Every time I waste money, I regret it."
          },
          {
            word_ja: "\u8A18\u5FF5[\u304D\u306D\u3093]",
            romaji: "kinen",
            meaning_bn: "\u09B8\u09CD\u09AE\u09BE\u09B0\u0995 / \u09B8\u09CD\u09AE\u09C3\u09A4\u09BF\u099A\u09BF\u09B9\u09CD\u09A8",
            meaning_en: "commemoration / memorial",
            part_of_speech: "noun",
            example_ja: "\u65C5\u884C[\u308A\u3087\u3053\u3046]\u306E\u305F\u3073\u306B\u8A18\u5FF5[\u304D\u306D\u3093]\u306E\u30DE\u30B0\u30CD\u30C3\u30C8\u3092\u8CB7[\u304B]\u3046\u3002",
            example_bn: "\u09AD\u09CD\u09B0\u09AE\u09A3\u09C7 \u09AF\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u098F\u0995\u099F\u09BF \u09B8\u09CD\u09AE\u09BE\u09B0\u0995 \u09AE\u09CD\u09AF\u09BE\u0997\u09A8\u09C7\u099F \u0995\u09BF\u09A8\u09BF\u0964",
            example_en: "Whenever I travel, I buy a commemorative magnet."
          },
          {
            word_ja: "\u65C5[\u305F\u3073]",
            romaji: "tabi",
            meaning_bn: "\u09AD\u09CD\u09B0\u09AE\u09A3 / \u09AF\u09BE\u09A4\u09CD\u09B0\u09BE",
            meaning_en: "trip / journey",
            part_of_speech: "noun",
            example_ja: "\u65C5[\u305F\u3073]\u3092\u3059\u308B\u305F\u3073\u306B\u65B0[\u3042\u305F\u3089]\u3057\u3044\u767A\u898B[\u306F\u3063\u3051\u3093]\u304C\u3042\u308B\u3002",
            example_bn: "\u09AD\u09CD\u09B0\u09AE\u09A3 \u0995\u09B0\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09AC\u09BE\u09B0\u0987 \u09A8\u09A4\u09C1\u09A8 \u0995\u09BF\u099B\u09C1 \u0986\u09AC\u09BF\u09B7\u09CD\u0995\u09BE\u09B0\u09C7\u09B0 \u0986\u09A8\u09A8\u09CD\u09A6 \u09A5\u09BE\u0995\u09C7\u0964",
            example_en: "Every time I travel, there are new discoveries."
          }
        ],
