            word_ja: "\u8CC7\u6599[\u3057\u308A\u3087\u3046]",
            romaji: "shiryou",
            meaning_bn: "\u09A8\u09A5\u09BF\u09AA\u09A4\u09CD\u09B0 / \u09A4\u09A5\u09CD\u09AF\u09B8\u09BE\u09AE\u0997\u09CD\u09B0\u09C0",
            meaning_en: "documents / materials",
