        grammar_points: [
          {
            point_id: "N3-G27-1",
            pattern_ja: "\u666E\u901A\u5F62[\u3075\u3064\u3046\u3051\u3044] (\u306A\u5F62+\u306A\uFF0F\u540D\u8A5E+\u306E) + \u305B\u3044\u3067",
            pattern_bn: "\u09A8\u09C7\u09A4\u09BF\u09AC\u09BE\u099A\u0995 \u0995\u09BE\u09B0\u09A3\u09C7 \u0986\u0995\u09CD\u09B7\u09C7\u09AA \u09AC\u09BE \u09A6\u09CB\u09B7\u09BE\u09B0\u09CB\u09AA",
            explanation_bn: "\u0985\u09A8\u09BE\u0995\u09BE\u0999\u09CD\u0995\u09CD\u09B7\u09BF\u09A4 \u09AA\u09B0\u09BF\u09B8\u09CD\u09A5\u09BF\u09A4\u09BF \u09B8\u09C3\u09B7\u09CD\u099F\u09BF \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09A8\u09BF\u09B0\u09CD\u09A6\u09BF\u09B7\u09CD\u099F \u0995\u09BE\u09B0\u09A3\u099F\u09BF\u0995\u09C7 \u09A6\u09BE\u09AF\u09BC\u09C0 \u0995\u09B0\u09BE\u0964",
            common_pitfalls: [
              "\u09AD\u09BE\u09B2\u09CB \u09AB\u09B2\u09BE\u09AB\u09B2\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u305B\u3044\u3067 \u09AC\u09B8\u09C7 \u09A8\u09BE; \u09A4\u0996\u09A8 \u5FC5\u305A \u304A\u304B\u3052\u3067 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964"
            ],
            examples: [
              {
                ja: "\u5927\u96E8[\u304A\u304A\u3042\u3081]\u306E\u305B\u3044\u3067\u96FB\u8ECA[\u3067\u3093\u3057\u3083]\u304C\u6B62[\u3068]\u307E\u308A\u3001\u9045\u523B[\u3061\u3053\u304F]\u3057\u3066\u3057\u307E\u3063\u305F\u3002",
                bn: "\u09AE\u09C1\u09B7\u09B2\u09A7\u09BE\u09B0\u09C7 \u09AC\u09C3\u09B7\u09CD\u099F\u09BF\u09B0 \u0995\u09BE\u09B0\u09A3\u09C7 \u099F\u09CD\u09B0\u09C7\u09A8 \u09AC\u09A8\u09CD\u09A7 \u09B9\u09AF\u09BC\u09C7 \u0997\u09BF\u09AF\u09BC\u09C7\u099B\u09BF\u09B2, \u09AF\u09BE\u09B0 \u09AB\u09B2\u09C7 \u0986\u09AE\u09BE\u09B0 \u09A6\u09C7\u09B0\u09BF \u09B9\u09AF\u09BC\u09C7 \u0997\u09C7\u09B2\u0964",
                en: "Because of heavy rain, the train stopped and I ended up being late."
              }
            ]
          }
        ],
        dialogue_scenario: {
          situation_bn: "\u0985\u09AB\u09BF\u09B8\u09C7 \u09A6\u09C7\u09B0\u09BF\u09A4\u09C7 \u0986\u09B8\u09BE\u09B0 \u09AA\u09B0 \u0995\u09CD\u09B7\u09AE\u09BE \u09AA\u09CD\u09B0\u09BE\u09B0\u09CD\u09A5\u09A8\u09BE \u0993 \u09AA\u09B0\u09BF\u09B8\u09CD\u09A5\u09BF\u09A4\u09BF\u09B0 \u09AC\u09CD\u09AF\u09BE\u0996\u09CD\u09AF\u09BE\u0964",
          situation_en: "Apologizing for being late due to train delays in Tokyo.",
          lines: [
            {
              speaker_ja: "\u30E9\u30D2\u30E0",
              speaker_en: "Rahim",
              line_ja: "\u5927\u5909[\u305F\u3044\u3078\u3093]\u7533[\u3082\u3046]\u3057\u8A33[\u308F\u3051]\u3054\u3056\u3044\u307E\u305B\u3093\u3002\u4EBA\u8EAB[\u3058\u3093\u3057\u3093]\u4E8B\u6545[\u3058\u3053]\u306E\u305B\u3044\u3067\u96FB\u8ECA[\u3067\u3093\u3057\u3083]\u304C\uFF13\uFF10\u5206[\u3055\u3093\u3058\u3085\u3063\u3077\u3093]\u9045[\u304A\u304F]\u308C\u307E\u3057\u305F\u3002",
              line_bn: "\u0985\u09A4\u09CD\u09AF\u09A8\u09CD\u09A4 \u0986\u09A8\u09CD\u09A4\u09B0\u09BF\u0995\u09AD\u09BE\u09AC\u09C7 \u0995\u09CD\u09B7\u09AE\u09BE \u09AA\u09CD\u09B0\u09BE\u09B0\u09CD\u09A5\u09A8\u09BE \u0995\u09B0\u099B\u09BF\u0964 \u09B2\u09BE\u0987\u09A8\u09C7 \u09A6\u09C1\u09B0\u09CD\u0998\u099F\u09A8\u09BE\u09B0 \u0995\u09BE\u09B0\u09A3\u09C7 \u099F\u09CD\u09B0\u09C7\u09A8\u099F\u09BF \u09E9\u09E6 \u09AE\u09BF\u09A8\u09BF\u099F \u09A6\u09C7\u09B0\u09BF\u09A4\u09C7 \u099A\u09B2\u09C7\u099B\u09C7\u0964",
              line_en: "I am extremely sorry. Because of an accident, the train was delayed by 30 minutes."
            },
            {
              speaker_ja: "\u8AB2\u9577[\u304B\u3061\u3087\u3046]",
              speaker_en: "Section Chief",
              line_ja: "\u96FB\u8ECA\u306E\u9045\u5EF6[\u3061\u3048\u3093]\u306A\u3089\u4ED5\u65B9[\u3057\u304B\u305F]\u304C\u306A\u3044\u3067\u3059\u306D\u3002\u7121\u4E8B[\u3076\u3058]\u3067\u4F55[\u306A\u306B]\u3088\u308A\u3067\u3059\u3002",
              line_bn: "\u099F\u09CD\u09B0\u09C7\u09A8\u09C7\u09B0 \u09A6\u09C7\u09B0\u09BF\u09B0 \u0995\u09BE\u09B0\u09A3\u09C7 \u09B9\u09B2\u09C7 \u09A4\u09CB \u0995\u09BF\u099B\u09C1 \u0995\u09B0\u09BE\u09B0 \u09A8\u09C7\u0987\u0964 \u0986\u09AA\u09A8\u09BF \u09A8\u09BF\u09B0\u09BE\u09AA\u09A6\u09C7 \u09AA\u09CC\u0981\u099B\u09C7\u099B\u09C7\u09A8 \u09B8\u09C7\u099F\u09BE\u0987 \u09AC\u09A1\u09BC \u0995\u09A5\u09BE\u0964",
              line_en: "If it's a train delay, it can't be helped. The most important thing is that you're safe."
            }
          ]
        },
