        japan_survival_tip: {
          title_bn: "\u0989\u099A\u09BF (\u30A6\u30C1) \u09AC\u09A8\u09BE\u09AE \u09B8\u09CB\u09A4\u09CB (\u30BD\u30C8) \u098F\u09B0 \u0995\u09C7\u0987\u0997\u09CB \u09B0\u09B9\u09B8\u09CD\u09AF",
          tip_bn: "\u09AC\u09BE\u0987\u09B0\u09C7\u09B0 \u0995\u09CD\u09B2\u09BE\u09AF\u09BC\u09C7\u09A8\u09CD\u099F\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u0995\u09A5\u09BE \u09AC\u09B2\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09CB\u09AE\u09CD\u09AA\u09BE\u09A8\u09BF\u09B0 \u09B8\u09BF\u0987\u0993 \u09AC\u09BE \u09B8\u09BF\u09A8\u09BF\u09AF\u09BC\u09B0 \u09AE\u09CD\u09AF\u09BE\u09A8\u09C7\u099C\u09BE\u09B0\u0993 \u0986\u09AA\u09A8\u09BE\u09B0 '\u0989\u099A\u09BF' (\u0998\u09B0\u09C7\u09B0 \u09B2\u09CB\u0995)\u0964 \u09A4\u09BE\u0987 \u09AC\u09BE\u0987\u09B0\u09C7\u09B0 \u09B2\u09CB\u0995\u09C7\u09B0 \u0995\u09BE\u099B\u09C7 \u09B8\u09BF\u0987\u0993-\u09B0 \u09A8\u09BE\u09AE\u09C7 '\u69D8' \u09AC\u09BE '\u3055\u3093' \u09AF\u09CB\u0997 \u0995\u09B0\u09AC\u09C7\u09A8 \u09A8\u09BE \u098F\u09AC\u0982 \u09B8\u09A8\u0995\u09C7\u0987\u0997\u09CB \u09AC\u09B2\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964 '\u793E\u9577\u306E\u5C71\u7530\u306F\u4E0D\u5728\u3067\u3059' (\u09AA\u09CD\u09B0\u09C7\u09B8\u09BF\u09A1\u09C7\u09A8\u09CD\u099F \u0987\u09AF\u09BC\u09BE\u09AE\u09BE\u09A6\u09BE \u098F\u0996\u09A8 \u09A8\u09C7\u0987) \u09AC\u09B2\u09BE\u0987 \u09AC\u09BF\u09B6\u09C1\u09A6\u09CD\u09A7 \u099C\u09BE\u09AA\u09BE\u09A8\u09BF \u0995\u09B0\u09CD\u09AA\u09CB\u09B0\u09C7\u099F \u09B0\u09C0\u09A4\u09BF\u0964",
          practical_action_bn: "\u0995\u09CD\u09B2\u09BE\u09AF\u09BC\u09C7\u09A8\u09CD\u099F\u0995\u09C7 \u09AB\u09CB\u09A8 \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u0995\u0996\u09A8\u09CB\u0987 '\u5C71\u7530\u793E\u9577\u306F\u304A\u3063\u3057\u3083\u3044\u307E\u3057\u305F' \u09AC\u09B2\u09AC\u09C7\u09A8 \u09A8\u09BE, \u09AC\u09B2\u09AC\u09C7\u09A8 '\u5F0A\u793E\u306E\u5C71\u7530\u304C\u7533\u3057\u3066\u304A\u308A\u307E\u3057\u305F'\u0964"
        },
