            meaning_bn: "\u0995\u09CB\u09A8\u09CB \u0997\u09B0\u09AE\u09BF\u09B2 \u09AC\u09BE \u09AD\u09C1\u09B2 \u09A8\u09C7\u0987",
            meaning_en: "there is no mistake / fully correct",
            part_of_speech: "expression",
