            word_ja: "\u8A66\u884C[\u3057\u3053\u3046]\u932F\u8AA4[\u3055\u304F\u3054]",
            romaji: "shikousakugo",
            meaning_bn: "\u09AC\u09BE\u09B0\u0982\u09AC\u09BE\u09B0 \u09AA\u09CD\u09B0\u099A\u09C7\u09B7\u09CD\u099F\u09BE \u0993 \u09AD\u09C1\u09B2 \u09B8\u0982\u09B6\u09CB\u09A7\u09A8 (\u099F\u09CD\u09B0\u09BE\u09AF\u09BC\u09BE\u09B2 \u0985\u09CD\u09AF\u09BE\u09A8\u09CD\u09A1 \u098F\u09B0\u09B0)",
