        bengali_bridge: {
          explanation_bn: "\u099C\u09BE\u09AA\u09BE\u09A8\u09BF \u09AF\u09CB\u0997\u09BE\u09AF\u09CB\u0997\u09C7\u09B0 \u0986\u09B8\u09B2 \u09AF\u09BE\u09A6\u09C1 \u09B9\u09B2\u09CB '\u0995\u09C1\u09B6\u09A8 \u0993\u09AF\u09BC\u09BE\u09B0\u09CD\u09A1' (\u30AF\u30C3\u30B7\u30E7\u30F3\u8A00\u8449)\u0964 \u0995\u09CB\u09A8\u09CB \u0995\u09A0\u09BF\u09A8 \u0985\u09A8\u09C1\u09B0\u09CB\u09A7 \u0995\u09B0\u09BE\u09B0 \u0986\u0997\u09C7 \u09AC\u09BE \u0995\u09BE\u0989\u0995\u09C7 \u0985\u09B8\u09AE\u09CD\u09AE\u09A4\u09BF \u099C\u09BE\u09A8\u09BE\u09A8\u09CB\u09B0 \u0986\u0997\u09C7 \u0986\u0998\u09BE\u09A4 \u09A8\u09B0\u09AE \u0995\u09B0\u09A4\u09C7 \u09AF\u09C7 \u09AC\u09BF\u09A8\u09AE\u09CD\u09B0 \u09AC\u09BE\u0995\u09CD\u09AF\u09BE\u0982\u09B6 \u09B8\u09BE\u09AE\u09A8\u09C7 \u09AC\u09B8\u09BE\u09A8\u09CB \u09B9\u09AF\u09BC, \u09A4\u09BE\u0995\u09C7 \u0995\u09C1\u09B6\u09A8 \u0993\u09AF\u09BC\u09BE\u09B0\u09CD\u09A1 \u09AC\u09B2\u09C7\u0964 \u09AF\u09C7\u09AE\u09A8: '\u0985\u09B6\u09C7\u09B7 \u09B8\u0982\u0995\u09CB\u099A\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AC\u09B2\u099B\u09BF...', '\u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u0985\u09B8\u09C1\u09AC\u09BF\u09A7\u09BE \u09A8\u09BE \u09B9\u09AF\u09BC...' \u0987\u09A4\u09CD\u09AF\u09BE\u09A6\u09BF\u0964",
          core_concept_bn: "\u0995\u09A0\u09BF\u09A8 \u0985\u09A8\u09C1\u09B0\u09CB\u09A7 \u09AC\u09BE \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09BE\u0996\u09CD\u09AF\u09BE\u09A8\u09C7\u09B0 \u09A4\u09C0\u09AC\u09CD\u09B0\u09A4\u09BE \u0995\u09AE\u09BF\u09AF\u09BC\u09C7 \u09AE\u09BE\u09B0\u09CD\u099C\u09BF\u09A4 \u0993 \u09AE\u09A7\u09C1\u09B0 \u0986\u09AC\u09B9\u09C7 \u0989\u09AA\u09B8\u09CD\u09A5\u09BE\u09AA\u09A8 \u0995\u09B0\u09BE\u0964",
          real_world_context_bn: "\u09B8\u09AE\u09AF\u09BC\u09B8\u09C0\u09AE\u09BE \u09AC\u09BE\u09A1\u09BC\u09BE\u09A8\u09CB\u09B0 \u0985\u09A8\u09C1\u09B0\u09CB\u09A7\u09C7 '\u6050\u308C\u5165\u308A\u307E\u3059\u304C' \u09AC\u09BE \u0995\u09CD\u09B2\u09BE\u09AF\u09BC\u09C7\u09A8\u09CD\u099F\u09C7\u09B0 \u09AA\u09CD\u09B0\u09B8\u09CD\u09A4\u09BE\u09AC \u09AC\u09BF\u09A8\u09C0\u09A4 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09BE\u0996\u09CD\u09AF\u09BE\u09A8\u09C7 '\u3042\u3044\u306B\u304F\u3067\u306F\u3054\u3056\u3044\u307E\u3059\u304C' \u099C\u09BE\u09AA\u09BE\u09A8\u09C7 \u09B8\u09B0\u09CD\u09AC\u099C\u09A8\u09C0\u09A8 \u09B8\u0982\u09B8\u09CD\u0995\u09C3\u09A4\u09BF\u0964",
          key_takeaway_bn: "\u6050\u7E2E\u3067\u3059\u304C, \u5DEE\u3057\u652F\u3048\u306A\u3051\u308C\u3070, \u3042\u3044\u306B\u304F\u3067\u3059\u304C, \u8AA0\u306B\u5FC3\u82E6\u3057\u3044\u306E\u3067\u3059\u304C + \u672C\u984C\u3002"
        },
