import { OAuth2Client } from "google-auth-library";
import dotenv2 from "dotenv";
dotenv2.config();
var googleClient = new OAuth2Client();
async function verifyGoogleIdToken(token) {
  if (!token || typeof token !== "string") {
    return null;
  }
  const cleanToken = token.trim();
  if (!cleanToken) {
    return null;
  }
  try {
    const audience = process.env.GOOGLE_CLIENT_ID || process.env.VITE_GOOGLE_CLIENT_ID || void 0;
    const ticket = await googleClient.verifyIdToken({
      idToken: cleanToken,
      audience: audience ? audience : void 0
    });
    const payload = ticket.getPayload();
    if (!payload || !payload.email || !payload.sub) {
      return null;
    }
    if (payload.email_verified === false) {
      return null;
    }
    const cleanEmail = payload.email.toLowerCase().trim();
    const displayName = payload.name || payload.given_name || cleanEmail.split("@")[0];
    return {
      sub: payload.sub,
      email: cleanEmail,
      name: displayName,
      picture: payload.picture,
      emailVerified: Boolean(payload.email_verified)
    };
  } catch (error) {
    return null;
  }
}

