        options: ["\u3044\u3061\u307E\u3093\u3048\u3093", "\u306B\u307E\u3093 \u3054\u305B\u3093\u3048\u3093", "\u3054\u305B\u3093\u3048\u3093", "\u3055\u3093\u307E\u3093\u3048\u3093"],
