var CANDIDATE_MODELS2 = [
  "gemini-2.5-flash",
  "gemini-3.7-flash",
  "gemini-flash-latest",
  "gemini-2.5-pro"
];
async function callGeminiJson(ai, prompt, stageName, timeoutMs = 25e3) {
  let lastError = null;
  for (const candidate of CANDIDATE_MODELS2) {
    try {
      const response = await Promise.race([
        ai.models.generateContent({
          model: candidate,
          contents: prompt,
          config: {
            temperature: 0.15,
            responseMimeType: "application/json"
          }
        }),
        new Promise(
          (_, reject) => setTimeout(() => reject(new Error(`Model timeout after ${timeoutMs}ms for ${candidate}`)), timeoutMs)
        )
      ]);
      if (response.text) {
        let cleaned = response.text.trim();
        if (cleaned.startsWith("```json")) cleaned = cleaned.slice(7);
        if (cleaned.startsWith("```")) cleaned = cleaned.slice(3);
        if (cleaned.endsWith("```")) cleaned = cleaned.slice(0, -3);
        cleaned = cleaned.trim();
        const parsed = JSON.parse(cleaned);
        return { data: parsed, modelUsed: candidate };
      }
    } catch (err) {
      console.warn(`[ContentEngine:${stageName}] Candidate ${candidate} attempt failed:`, err?.message || err);
      lastError = err;
    }
  }
  throw new Error(`[Pipeline Error at ${stageName}]: All candidate models failed. Last failure: ${lastError?.message || "Empty response"}`);
}
